// Canary weights to walk through, and the per-step measured error counts.
// threshold = max tolerated error rate (1%). A step PROMOTES only if its
// error rate <= threshold; the first breach ROLLS BACK and stops the ramp.
const threshold = 0.01;
const steps = [
  { weight: 5,  requests: 2000, errors: 6 },   // 0.30%
  { weight: 25, requests: 2000, errors: 14 },  // 0.70%
  { weight: 50, requests: 2000, errors: 240 }, // 12.00% -> breach
  { weight: 100, requests: 2000, errors: 0 },
];

// Walk the steps: a step's error rate = errors / requests.
// If a step's rate > threshold, log 'ROLLBACK at <weight>%' and stop.
// If no step breaches, log 'PROMOTE 100%'.

// Kubernetes rounding: maxSurge rounds UP, maxUnavailable rounds DOWN.
// maxPods   = replicas + ceil(replicas * surgePct / 100)
// minReady  = replicas - floor(replicas * unavailPct / 100)
const replicas = 10;
// risky default: surge 25%, unavailable 25%
// safe zero-downtime: surge 10% (1 pod), unavailable 0%
//
// Compute maxPods/minReady for both configs and print exactly:
// default maxPods=<d.maxPods> minReady=<d.minReady> | zero-downtime maxPods=<z.maxPods> minReady=<z.minReady>

